def default_intf_enabled(name='', sysdefs=None, mode=None):
    """Compute the default administrative enabled/shutdown state for an
    interface based on its name/type, the device's user system defaults
    (USD) and the target mode.

    - loopback and port-channel interfaces default to enabled
    - L2 interfaces follow the 'L2_enabled' system default
    - L3 interfaces default to enabled on N3K/N5K/N6K platforms and
      disabled on N7K/N9K platforms
    """
    if sysdefs is None:
        sysdefs = {}

    if_type = get_interface_type(name)

    if if_type in ('loopback', 'portchannel'):
        return True

    if mode == 'layer2':
        return sysdefs.get('L2_enabled')

    if mode == 'layer3':
        return sysdefs.get('L3_enabled')

    # Fall back to the device-wide default mode when no explicit mode given
    if mode is None:
        mode = sysdefs.get('mode', 'layer2')
        if mode == 'layer2':
            return sysdefs.get('L2_enabled')
        return sysdefs.get('L3_enabled')

    return None
