+import MemberAvatar from "../components/views/avatars/MemberAvatar";
+import { ButtonEvent } from "../components/views/elements/AccessibleButton";
+
+interface UsePermalinkArgs {
+    room?: Room;
+    type?: PillType;
+    url?: string;
+}
+
+interface UsePermalinkResult {
+    avatar: React.ReactElement | null;
+    text: string | null;
+    onClick: ((e: ButtonEvent) => void) | null;
+    resourceId: string | null;
+    type: PillType | "space" | null;
+}
+
+export function usePermalink({ room, type, url }: UsePermalinkArgs): UsePermalinkResult {
+    const [member, setMember] = useState<RoomMember | null>(null);
+    const [resolvedRoom, setResolvedRoom] = useState<Room | null>(null);
+
+    useEffect(() => {
+        let resourceId: string | null = null;
+        let prefix: string;
+
+        if (url) {
+            if (url.startsWith("matrix:")) {
+                const parts = parsePermalink(url);
+                resourceId = parts.primaryEntityId;
+                prefix = parts.sigil;
+            } else {
+                resourceId = getPrimaryPermalinkEntity(url);
+                prefix = resourceId ? resourceId[0] : undefined;
+            }
+        }
+
+        const resolvedType =
+            type ||
+            ({
+                "@": PillType.UserMention,
+                "#": PillType.RoomMention,
+                "!": PillType.RoomMention,
+            } as Record<string, PillType>)[prefix];
+
+        if (resolvedType === PillType.AtRoomMention) {
+            setResolvedRoom(room);
+        } else if (resolvedType === PillType.UserMention && resourceId) {
+            const localMember = room?.getMember(resourceId);
+            if (localMember) {
+                setMember(localMember);
+            } else {
+                const newMember = new RoomMember(null, resourceId);
+                setMember(newMember);
+                MatrixClientPeg.get()
+                    .getProfileInfo(resourceId)
+                    .then((resp) => {
+                        newMember.name = resp.displayname;
+                        newMember.rawDisplayName = resp.displayname;
+                        setMember(newMember);
+                    })
+                    .catch((err) => {
+                        logger.error("Could not retrieve profile data for " + resourceId + ":", err);
+                    });
+            }
+        } else if (resolvedType === PillType.RoomMention && resourceId) {
+            const localRoom =
+                resourceId[0] === "#"
+                    ? MatrixClientPeg.get()
+                          .getRooms()
+                          .find((r) => r.getCanonicalAlias() === resourceId || r.getAltAliases().includes(resourceId))
+                    : MatrixClientPeg.get().getRoom(resourceId);
+            setResolvedRoom(localRoom || null);
+        }
+
+        // Store resolvedType in a ref or return it via closure
+        // We need to expose resolvedType in the return value
+        // Since hooks must return a stable object, we compute it here
+    }, [url, type, room]);
+
+    // Recompute resolvedType synchronously for the return value
+    let resourceId: string | null = null;
+    let prefix: string;
+    if (url) {
+        if (url.startsWith("matrix:")) {
+            const parts = parsePermalink(url);
+            resourceId = parts.primaryEntityId;
+            prefix = parts.sigil;
+        } else {
+            resourceId = getPrimaryPermalinkEntity(url);
+            prefix = resourceId ? resourceId[0] : undefined;
+        }
+    }
+    const resolvedType =
+        type ||
+        ({
+            "@": PillType.UserMention,
+            "#": PillType.RoomMention,
+            "!": PillType.RoomMention,
+        } as Record<string, PillType>)[prefix];
+
+    let text: string | null = null;
+    let avatar: React.ReactElement | null = null;
+    let onClick: ((e: ButtonEvent) => void) | null = null;
+
+    if (resolvedType === PillType.AtRoomMention) {
+        text = "@room";
+        if (room) {
+            avatar = <RoomAvatar room={room} width={16} height={16} aria-hidden="true" />;
+        }
+    } else if (resolvedType === PillType.UserMention) {
+        if (member) {
+            text = member.rawDisplayName || member.userId;
+            avatar = <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />;
+            onClick = (e: ButtonEvent) => {
+                e.preventDefault();
+                dis.dispatch({
+                    action: Action.ViewUser,
+                    member: member,
+                });
+            };
+        }
+    } else if (resolvedType === PillType.RoomMention) {
+        if (resolvedRoom) {
+            text = resolvedRoom.name || resourceId;
+            avatar = <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" />;
+        }
+    }
+
+    const finalType: PillType | "space" | null =
+        resolvedType === PillType.RoomMention && resolvedRoom?.isSpaceRoom() ? "space" : resolvedType;
+
+    return {
+        avatar,
+        text,
+        onClick,
+        resourceId,
+        type: finalType,
